35	func newProjectCreateCmd() *cobra.Command {
36		var (
37			ownerID   string
38			ownerType string
39			region    string
40		)
41		cmd := &cobra.Command{
42			Use:   "create <name>",
43			Short: "Create a project under an org or account",
44			Long: "Creates a project owned by an org or an account. --owner is the " +
45				"owning org (name or ULID) or account (github:handle or ULID), and " +
46				"--owner-type selects which (org or account).",
47			Example: "  # Project under an org (by name)\n" +
48				"  entire project create widgets --owner acme --owner-type org\n\n" +
49				"  # Project owned by an account (by handle)\n" +
50				"  entire project create widgets --owner github:alice --owner-type account",
51			Args: cobra.ExactArgs(1),
52			RunE: func(cmd *cobra.Command, args []string) error {
53				cmd.SilenceUsage = true
54				ot, err := parseProjectOwnerType(ownerType)
55				if err != nil {
56					return err
57				}
58				return runCoreJSON(cmd, func(ctx context.Context, c *coreapi.Client) (any, error) {
59					// Orgs are addressed by name, accounts by github:handle; both
60					// also accept a raw ULID.
61					var ownerRef string
62					switch ot {
63					case coreapi.CreateProjectInputBodyOwnerTypeOrg:
64						ownerRef, err = resolveOrgRef(ctx, c, ownerID)
65					case coreapi.CreateProjectInputBodyOwnerTypeAccount:
66						ownerRef, err = resolveAccountRef(ctx, c, ownerID)
67					}
68					if err != nil {
69						return nil, err
70					}
71					body := &coreapi.CreateProjectInputBody{
72						Name:      args[0],
73						OwnerId:   ownerRef,
74						OwnerType: ot,
75					}
76					if region != "" {
77						body.Region = coreapi.NewOptString(region)
78					}
79					return c.CreateProject(ctx, body)
80				})
81			},
82		}
83		cmd.Flags().StringVar(&ownerID, "owner", "", "owning org (name or ULID), or account (github:handle or ULID) (required)")
84		cmd.Flags().StringVar(&ownerType, "owner-type", "org", "owner kind: org or account")
85		cmd.Flags().StringVar(&region, "region", "", "jurisdiction slug (defaults to the server's home jurisdiction)")
86		markRequired(cmd, "owner")
87		return cmd
88	}
