98					// Both the global and org-scoped list endpoints filter by name
99					// server-side (case-insensitive), returning the single match under
100					// the response's `project` field (or 404 → empty result, not an
101					// error). Without --name we page through the full list.
102					if org != "" {
103						orgID, err := resolveOrgRef(ctx, c, org)
104						if err != nil {
105							return nil, err
106						}
107						if name != "" {
108							out, err := c.ListOrgProjects(ctx, coreapi.ListOrgProjectsParams{OrgId: orgID, Name: coreapi.NewOptString(name)})
109							if err != nil {
110								if isCoreNotFound(err) {
111									return nil, nil
112								}
113								return nil, err
114							}
115							return toProjectList(out.Project), nil
116						}
117						return fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]coreapi.Project, string, error) {
118							params := coreapi.ListOrgProjectsParams{OrgId: orgID}
119							if cursor != "" {
120								params.PageToken = coreapi.NewOptString(cursor)
121							}
122							out, err := c.ListOrgProjects(ctx, params)
123							if err != nil {
124								return nil, "", err
125							}
126							return out.Projects, out.NextPageToken.Or(""), nil
127						})
128					}
129					if name != "" {
130						out, err := c.ListProjects(ctx, coreapi.ListProjectsParams{Name: coreapi.NewOptString(name)})
131						if err != nil {
132							if isCoreNotFound(err) {
133								return nil, nil
134							}
135							return nil, err
136						}
137						return toProjectList(out.Project), nil
138					}
139					return fetchAllPages(ctx, func(ctx context.Context, cursor string) ([]coreapi.Project, string, error) {
140						params := coreapi.ListProjectsParams{}
141						if cursor != "" {
142							params.PageToken = coreapi.NewOptString(cursor)
143						}
144						out, err := c.ListProjects(ctx, params)
145						if err != nil {
146							return nil, "", err
147						}
148						return out.Projects, out.NextPageToken.Or(""), nil
149					})
150				})
151			},
152		}
153		cmd.Flags().StringVar(&name, "name", "", "filter by exact project name")
154		cmd.Flags().StringVar(&org, "org", "", "list projects owned by this org (name or ULID)")
