194	// parseProjectOwnerType maps the --owner-type flag to the generated enum,
195	// rejecting anything but org/account at the CLI boundary so the user gets
196	// a clear message instead of a server 422.
197	func parseProjectOwnerType(s string) (coreapi.CreateProjectInputBodyOwnerType, error) {
198		switch s {
199		case "org":
200			return coreapi.CreateProjectInputBodyOwnerTypeOrg, nil
201		case "account":
202			return coreapi.CreateProjectInputBodyOwnerTypeAccount, nil
203		default:
204			// Plain error: the create RunE sets SilenceUsage, and main.go
205			// prints plain errors (a SilentError would be swallowed).
206			return "", fmt.Errorf("invalid --owner-type %q: must be \"org\" or \"account\"", s)
207		}
208	}
