1	package cli
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"strings"
9	
10		"github.com/spf13/cobra"
11	
12		"github.com/entireio/cli/internal/coreapi"
13	)
14	
15	// newRepoCmd is the hidden `entire repo` command group: control-plane
16	// repository lifecycle (create, list within a project, get, delete) plus the
17	// `clone` convenience that resolves a mirror and shells out to `git clone`.
18	// Other git content operations (log, diff, …) remain intentionally out of scope
19	// here. Surfaced via `entire labs`.
20	func newRepoCmd() *cobra.Command {
21		cmd := &cobra.Command{
22			Use:    "repo",
23			Short:  "Manage Entire repositories",
24			Hidden: true,
25		}
26		addControlPlaneFlags(cmd)
27		cmd.AddCommand(newRepoCreateCmd())
28		cmd.AddCommand(newRepoListCmd())
29		cmd.AddCommand(newRepoGetCmd())
30		cmd.AddCommand(newRepoDeleteCmd())
31		cmd.AddCommand(newRepoCloneCmd())
32		cmd.AddCommand(newRepoMirrorCmd())
33		cmd.AddCommand(newRepoVisibilityCmd())
34		return cmd
35	}
36	
37	// repoColumns is the human table/field view of a repo, shared by list and
38	// get. CLUSTER/STATE come from optional fields, shown as "-" when unset.
39	var repoColumns = []string{"ID", "NAME", "PROJECT", "CLUSTER", "STATE"}
40	
41	func repoRow(r coreapi.Repo) []string {
42		state := ""
43		if v, ok := r.State.Get(); ok {
44			state = string(v)
45		}
46		return []string{r.ID, r.Name, r.OwningProjectId, r.ClusterHost.Or("-"), state}
47	}
48	
49	// repoDetailColumns / repoDetailRow extend the shared repo view with the
50	// entire:// clone URL for the single-repo `get` output. The list view stays on
51	// the lean repoColumns — a full clone URL per row would bloat the table — but a
52	// person inspecting one repo wants the URL they can paste into `git clone`
53	// (COR-699). REMOTE is "-" until the repo is provisioned enough to have a
54	// resolvable cluster host + path.
55	var repoDetailColumns = []string{"ID", "NAME", "PROJECT", "CLUSTER", "STATE", "REMOTE"}
56	
57	func repoDetailRow(r coreapi.Repo) []string {
58		remote := repoRemoteURL(r)
59		if remote == "" {
60			remote = "-"
61		}
62		return append(repoRow(r), remote)
63	}
64	
65	// repoRemoteURL synthesizes the entire:// clone/remote URL for a repo from
66	// its resolved cluster host and path — the form `git clone` and
67	// `git remote add` accept, which git-remote-entire reads back as the repo
68	// slug from the URL path. Returns "" when either coordinate is missing (a
69	// still-provisioning repo may not have them yet); a half-formed URL is worse
70	// than none.
71	func repoRemoteURL(r coreapi.Repo) string {
72		host := strings.TrimSpace(r.ClusterHost.Or(""))
73		path := strings.TrimSpace(r.Path.Or(""))
74		if host == "" || path == "" {
75			return ""
76		}
77		return "entire://" + host + "/" + strings.TrimPrefix(path, "/")
78	}
79	
80	// repoCreateOutput renders a created repo as JSON with a synthesized `remote`
81	// field merged in — the entire:// URL callers paste into `git clone` or
82	// `git remote add`. The repo carries a custom marshaler plus arbitrary
83	// additional properties, so it can't simply be embedded in a wrapper struct;
84	// instead it's round-tripped through its own encoder and the remote is merged
85	// into the resulting object. The synthesis only fills a gap: if the wire
86	// object already carries a `remote` (a future first-class field, or one
87	// arriving via additional properties) it's left untouched, so the
88	// server-provided value always wins. The field is omitted when the clone
89	// coordinates aren't resolvable yet rather than emitted half-formed.
90	func repoCreateOutput(r *coreapi.Repo) (any, error) {
91		if r == nil {
92			return nil, errors.New("nil repo")
93		}
94		raw, err := json.Marshal(r)
95		if err != nil {
96			return nil, fmt.Errorf("encode repo: %w", err)
97		}
98		var obj map[string]json.RawMessage
99		if err := json.Unmarshal(raw, &obj); err != nil {
100			return nil, fmt.Errorf("decode repo: %w", err)
101		}
102		if _, ok := obj["remote"]; !ok {
103			if remote := repoRemoteURL(*r); remote != "" {
104				encoded, err := json.Marshal(remote)
105				if err != nil {
106					return nil, fmt.Errorf("encode remote: %w", err)
107				}
108				obj["remote"] = encoded
109			}
110		}
111		return obj, nil
112	}
113	
