219	// repoVisibility is the field/JSON view shared by the visibility get/set
220	// verbs. Repo is the reference the user passed (name or ULID); Visibility is
221	// the server's authoritative value after the call.
222	type repoVisibility struct {
223		Repo       string `json:"repo"`
224		Visibility string `json:"visibility"`
225	}
226	
227	var visibilityColumns = []string{"REPO", "VISIBILITY"}
228	
229	func visibilityRow(v repoVisibility) []string {
230		return []string{v.Repo, v.Visibility}
231	}
232	
233	// parseVisibility maps the CLI argument to the wire enum, rejecting anything
234	// other than the two accepted values so a typo fails fast client-side rather
235	// than as an opaque 422 from the server.
236	func parseVisibility(s string) (coreapi.SetRepoVisibilityInputBodyVisibility, error) {
237		switch s {
238		case "public":
239			return coreapi.SetRepoVisibilityInputBodyVisibilityPublic, nil
240		case "private":
241			return coreapi.SetRepoVisibilityInputBodyVisibilityPrivate, nil
242		default:
243			return "", fmt.Errorf("invalid visibility %q: must be \"public\" or \"private\"", s)
244		}
245	}
