247	// newRepoVisibilityCmd groups the read/write verbs for a repo's visibility.
248	// "public" sets the SpiceDB public_viewer wildcard, which grants pull (read)
249	// to any authenticated account but never push or manage; "private" restricts
250	// the repo to explicit grantees. The data plane still requires authentication,
251	// so "public" means read-only-to-any-user, not anonymous/unauthenticated.
252	func newRepoVisibilityCmd() *cobra.Command {
253		cmd := &cobra.Command{
254			Use:   "visibility",
255			Short: "Get or set a repository's visibility",
256		}
257		cmd.AddCommand(newRepoVisibilityGetCmd())
258		cmd.AddCommand(newRepoVisibilitySetCmd())
259		return cmd
260	}
