12	// parseOrgRole maps the --role flag for `entire grant org add` to the
13	// generated enum, rejecting unknown values at the CLI boundary so the
14	// user gets a clear message instead of a server 422. Mirrors
15	// parseProjectOwnerType. The empty string means "use the server default
16	// (member)" and is the caller's signal to omit the field entirely; it is
17	// not handled here.
18	func parseOrgRole(s string) (coreapi.AddOrgMemberInputBodyRole, error) {
19		switch s {
20		case "owner":
21			return coreapi.AddOrgMemberInputBodyRoleOwner, nil
22		case "admin":
23			return coreapi.AddOrgMemberInputBodyRoleAdmin, nil
24		case "member":
25			return coreapi.AddOrgMemberInputBodyRoleMember, nil
26		default:
27			return "", fmt.Errorf("invalid --role %q: must be \"owner\", \"admin\", or \"member\"", s)
28		}
29	}
