324	// revokeGrantee performs the shared grantee-revocation routing for projects and
325	// repos: a ULID grantee takes the typed-id route (revokeByID); a provider:handle
326	// is resolved to its provider account first and takes the by-provider route
327	// (revokeByProvider). target ("project"/"repo") and ref name the grant in the
328	// success message.
329	func revokeGrantee(
330		ctx context.Context,
331		cmd *cobra.Command,
332		c *coreapi.Client,
333		target, ref, grantee string,
334		revokeByID func() error,
335		revokeByProvider func(provider, providerUserID string) error,
336	) error {
337		if looksLikeULID(grantee) {
338			return revokeGrant(cmd, "Revoked", fmt.Sprintf("account %s from %s %s", grantee, target, ref), revokeByID)
339		}
340		provider, providerUserID, err := resolveGranteeProvider(ctx, c, grantee)
341		if err != nil {
342			return err
343		}
344		return revokeGrant(cmd, "Revoked", fmt.Sprintf("%s from %s %s", grantee, target, ref), func() error {
345			return revokeByProvider(provider, providerUserID)
346		})
347	}
