473	// revokeGrant runs a grant-removal API call idempotently. A 404 means the
474	// grantee already has no such grant — the desired end state — so it's reported
475	// as a no-op rather than surfaced as a raw error, matching runControlPlaneDelete.
476	// verb is the success word ("Revoked"/"Removed"); subject describes the grant,
477	// e.g. "github:alice from repo acme".
478	func revokeGrant(cmd *cobra.Command, verb, subject string, revoke func() error) error {
