66	// runControlPlaneDelete is the shared body of the destructive `delete` verbs
67	// (org/project/repo). It resolves the target ref to a ULID, gates on a
68	// confirmation prompt (bypassed by --force/--yes), deletes, and reports the
69	// resolved identifier. noun names the resource ("org"); ref is the user's
70	// original argument, shown alongside the resolved ULID. resolve and del isolate
71	// the per-resource API calls.
72	func runControlPlaneDelete(
73		cmd *cobra.Command,
74		noun, ref string,
75		resolve func(context.Context, *coreapi.Client) (string, error),
76		del func(context.Context, *coreapi.Client, string) error,
77	) error {
78		force := forceRequested(cmd)
79		return runCore(cmd, func(ctx context.Context, c *coreapi.Client) error {
80			id, err := resolve(ctx, c)
81			if err != nil {
82				return err
83			}
84			label := noun + " " + resolvedRefLabel(ref, id)
85			proceed, err := confirmControlPlaneDeletion(ctx, cmd.OutOrStdout(), label, force, interactive.CanPromptInteractively())
86			if err != nil {
87				return err
88			}
89			if !proceed {
90				return nil
91			}
92			if err := del(ctx, c, id); err != nil {
93				// Idempotent delete: a resource that's already gone (a 404 from the
94				// delete call — e.g. a ULID passed straight through, or a concurrent
95				// delete) is the desired end state, not an error.
96				if isCoreNotFound(err) {
97					cmd.Printf("%s not found; nothing to delete\n", label)
98					return nil
99				}
100				return err
101			}
102			cmd.Printf("Deleted %s\n", label)
103			return nil
104		})
105	}
