107	// confirmControlPlaneDeletion gates a destructive control-plane delete. With
108	// force it proceeds silently. Otherwise it requires an interactive terminal:
109	// with none it refuses (returns an error) rather than deleting unprompted; with
110	// one it shows a confirmation form. canPrompt is passed in (not queried) so the
111	// decision is unit-testable without a TTY. label is the human description of
112	// the target, e.g. `org acme (01J…)`.
113	func confirmControlPlaneDeletion(ctx context.Context, w io.Writer, label string, force, canPrompt bool) (bool, error) {
114		if force {
115			return true, nil
116		}
117		if !canPrompt {
118			return false, fmt.Errorf("refusing to delete %s without confirmation; pass --force", label)
119		}
120		// huh opens the TTY during form startup regardless of context state, so
121		// guard explicitly to honor an already-cancelled command context.
122		if ctx.Err() != nil {
123			return false, nil //nolint:nilerr // cancelled context is a clean skip, not an error
124		}
125		confirmed := false
126		form := NewAccessibleForm(
127			huh.NewGroup(huh.NewConfirm().Title(fmt.Sprintf("Delete %s?", label)).Value(&confirmed)),
128		)
129		if err := form.RunWithContext(ctx); err != nil {
130			// A user abort (Esc) or context cancel (Ctrl+C) is a clean cancel, not
131			// an error — mirror confirmTrailDeletion.
132			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
133				return false, nil
134			}
135			return false, fmt.Errorf("deletion prompt: %w", err)
136		}
137		if !confirmed {
138			fmt.Fprintln(w, "Deletion cancelled.")
139			return false, nil
140		}
141		return true, nil
142	}
