181	// fetchAllPages drives a keyset-paginated list endpoint to completion: it
182	// calls fetch with an empty cursor, then re-calls it with each returned
183	// nextPageToken until the cursor comes back empty, concatenating every page.
184	// The control plane caps the page size (and may cap it further than a caller
185	// requests), so a single call only returns one page — list commands must loop
186	// or they silently truncate. The next==cursor guard turns a misbehaving server
187	// that fails to advance the cursor into an error instead of an infinite loop.
188	func fetchAllPages[T any](ctx context.Context, fetch func(ctx context.Context, cursor string) (items []T, next string, err error)) ([]T, error) {
189		var all []T
190		cursor := ""
191		for {
192			items, next, err := fetch(ctx, cursor)
193			if err != nil {
194				return nil, err
195			}
196			all = append(all, items...)
197			if next == "" {
198				return all, nil
199			}
200			if next == cursor {
201				return nil, fmt.Errorf("pagination did not advance (cursor %q repeated)", next)
202			}
203			cursor = next
204		}
205	}
