223	// tableStyles holds the foreground styles for the human table/field views,
224	// matching the activity/session palette: gray ("8") for headers and
225	// secondary cells, white ("7") for the primary (first-column) value. When
226	// color is disabled (non-TTY, NO_COLOR — e.g. piped output and tests) the
227	// styles are no-ops and output is plain.
228	type tableStyles struct {
229		enabled bool
230		header  lipgloss.Style
231		primary lipgloss.Style
232		cell    lipgloss.Style
233	}
234	
235	func newTableStyles(w io.Writer) tableStyles {
236		if !shouldUseColor(w) {
237			return tableStyles{}
238		}
239		return tableStyles{
240			enabled: true,
241			header:  lipgloss.NewStyle().Foreground(lipgloss.Color("8")).Bold(true),
242			primary: lipgloss.NewStyle().Foreground(lipgloss.Color("7")),
243			cell:    lipgloss.NewStyle().Foreground(lipgloss.Color("8")),
244		}
245	}
246	
247	// style applies s to text only when color is enabled; otherwise it returns
248	// text unchanged so padding math and plain output stay correct.
249	func (t tableStyles) style(s lipgloss.Style, text string) string {
250		if !t.enabled {
251			return text
252		}
253		return s.Render(text)
254	}
255	
256	// columnStyle picks the foreground for a data cell: the first column is the
257	// primary identifier (white), the rest are secondary (gray).
258	func (t tableStyles) columnStyle(col int) lipgloss.Style {
259		if col == 0 {
260			return t.primary
261		}
262		return t.cell
263	}
264	
265	// printTable writes headers plus one row per item, columns aligned on the
266	// plain-text widths so ANSI color codes don't throw off the layout (they're
267	// applied after padding). Callers handle the empty case.
268	func printTable[T any](w io.Writer, headers []string, items []T, row func(T) []string) error {
269		st := newTableStyles(w)
270		rows := make([][]string, len(items))
271		for i, it := range items {
272			rows[i] = row(it)
273		}
274		widths := columnWidths(headers, rows)
275	
276		var b strings.Builder
277		writeTableRow(&b, headers, widths, func(int) lipgloss.Style { return st.header }, st)
278		for _, r := range rows {
279			writeTableRow(&b, r, widths, st.columnStyle, st)
280		}
281		if _, err := io.WriteString(w, b.String()); err != nil {
282			return fmt.Errorf("render table: %w", err)
283		}
284		return nil
285	}
286	
287	// printFields writes a single record as aligned "FIELD  value" lines: the
288	// label in header gray, the value in the same primary/secondary color the
289	// list view would give that column.
290	func printFields(w io.Writer, headers, values []string) error {
291		st := newTableStyles(w)
292		labelWidth := 0
293		for _, h := range headers {
294			if n := lipgloss.Width(h); n > labelWidth {
295				labelWidth = n
296			}
297		}
298		var b strings.Builder
299		for i, h := range headers {
300			var v string
301			if i < len(values) {
302				v = values[i]
303			}
304			label := st.style(st.header, h+strings.Repeat(" ", labelWidth-lipgloss.Width(h)))
305			b.WriteString(label)
306			b.WriteString("  ")
307			b.WriteString(st.style(st.columnStyle(i), v))
308			b.WriteByte('\n')
309		}
310		if _, err := io.WriteString(w, b.String()); err != nil {
311			return fmt.Errorf("render fields: %w", err)
312		}
313		return nil
314	}
315	
316	// columnWidths returns the max plain-text width of each column across the
317	// headers and all rows.
318	func columnWidths(headers []string, rows [][]string) []int {
319		widths := make([]int, len(headers))
320		for i, h := range headers {
321			widths[i] = lipgloss.Width(h)
322		}
323		for _, r := range rows {
324			for i, c := range r {
325				if i < len(widths) && lipgloss.Width(c) > widths[i] {
326					widths[i] = lipgloss.Width(c)
327				}
328			}
329		}
330		return widths
331	}
332	
333	// writeTableRow pads each cell to its column width on the plain text, then
334	// styles it — so alignment is computed before any ANSI codes are added.
335	// The final column isn't padded, avoiding trailing whitespace.
336	func writeTableRow(b *strings.Builder, cells []string, widths []int, styleFor func(col int) lipgloss.Style, st tableStyles) {
337		for i, c := range cells {
338			last := i == len(cells)-1
339			padded := c
340			if !last && i < len(widths) {
341				padded = c + strings.Repeat(" ", widths[i]-lipgloss.Width(c))
342			}
343			b.WriteString(st.style(styleFor(i), padded))
344			if !last {
345				b.WriteString("  ")
346			}
347		}
348		b.WriteByte('\n')
349	}
