395	// runCoreClient owns the control-plane preamble shared by the active-context
396	// (runCore) and cluster-addressed (runCoreForCluster) variants: silence usage,
397	// opt into plain-HTTP token exchange if requested, build the client via
398	// newClient, run fn, and map API errors. The only difference between the two
399	// variants is which core newClient dials.
400	func runCoreClient(cmd *cobra.Command, newClient func(context.Context) (*coreapi.Client, error), fn func(ctx context.Context, c *coreapi.Client) error) error {
401		cmd.SilenceUsage = true
402		// Opt into plain-HTTP token exchange before the client (and its lazily
403		// built token manager) is constructed — the manager freezes the
404		// setting on first use.
405		if insecureHTTPRequested(cmd) {
406			auth.EnableInsecureHTTP()
407		}
408		client, err := newClient(cmd.Context())
409		if err != nil {
410			return fmt.Errorf("connect to Entire control plane: %w", err)
411		}
412		if err := fn(cmd.Context(), client); err != nil {
413			return renderCoreError(err)
414		}
415		return nil
416	}
