430	// renderCoreError converts a Core API error into the server's
431	// problem-detail message (so users see "organization name already taken"
432	// rather than ogen's decode-wrapped string), falling back to the raw error
433	// for transport/local failures. It returns a plain error, not a
434	// SilentError: main.go prints plain errors, and runCore has already set
435	// SilenceUsage, so the message reaches the user without a usage dump. (A
436	// SilentError here would be swallowed — main.go skips printing those —
437	// leaving e.g. a 409 conflict with no output.)
438	func renderCoreError(err error) error {
439		if err == nil {
440			return nil
441		}
442		if msg := coreapi.APIError(err); msg != "" {
443			return errors.New(msg)
444		}
445		return err
446	}
