13	// Control-plane commands reference orgs and projects by their parent ULID in
14	// many places (repo create --project, project create --owner, grant org/project
15	// <id>, …). ULIDs are unfriendly to type, so these refs also accept a human
16	// name: looksLikeULID decides which form was given, and the resolveXRef helpers
17	// turn a name into its ULID. A ULID is always passed straight through with no
18	// network call. A name is resolved by the control plane's O(1), case-insensitive
19	// by-name lookup (the server matches on lower(name) and returns the single match
20	// under the response's singular `org`/`project` field, or 404) — the CLI never
21	// lists everything and filters client-side.
22	
23	// providerGitHub is the identity-provider slug for GitHub-backed accounts, the
24	// provider half of a qualified grantee handle like "github:alice". GitHub is the
25	// only provider with backing accounts today; other slugs resolve once they exist
26	// server-side. (Distinct from setup.go's checkpointProviderGitHub, which names
27	// the checkpoint hosting provider — same string, unrelated concern.)
28	const providerGitHub = "github"
29	
30	// looksLikeULID reports whether s has the shape of a ULID: 26 characters drawn
31	// from Crockford base32 (digits plus uppercase letters, excluding I, L, O, U).
32	// The check is shape-only and case-insensitive on the alphabet; it never hits
33	// the network. A name that happened to be 26 valid base32 characters would be
34	// misread as an id, but real org/project names don't take that form, and the
35	// user can always fall back to the explicit ULID.
36	func looksLikeULID(s string) bool {
37		if len(s) != 26 {
38			return false
39		}
40		for _, r := range strings.ToUpper(s) {
41			switch {
42			case r >= '0' && r <= '9':
43			case r >= 'A' && r <= 'Z' && r != 'I' && r != 'L' && r != 'O' && r != 'U':
44			default:
45				return false
46			}
47		}
48		return true
49	}
